// Builds the Claude Code skill, the Cursor rule and the AGENTS.md section
// from one source (skill-src/guide.md), so the three never drift apart.

export type Target = 'skill' | 'cursor' | 'agents';

export const TARGETS: readonly Target[] = ['skill', 'cursor', 'agents'];

/** Where each generated file lives in this repository. */
export const OUTPUT_PATHS: Record<Target, string> = {
  skill: 'skills/rtl/SKILL.md',
  cursor: 'cursor/rtl.mdc',
  agents: 'codex/AGENTS.md',
};

export const AGENTS_START = '<!-- rtl-skill:start -->';
export const AGENTS_END = '<!-- rtl-skill:end -->';

export interface SkillMeta {
  name: string;
  description: string;
  cursor: { description: string; globs: string; alwaysApply: boolean };
}

const ONLY_OPEN = /^<!--\s*only:\s*([a-z,\s]+?)\s*-->\s*$/;
const ONLY_CLOSE = /^<!--\s*end only\s*-->\s*$/;
const FENCE = /^(```|~~~)/;

/** Keeps the lines meant for this target and drops the `only` markers. */
export function filterForTarget(source: string, target: Target): string {
  const out: string[] = [];
  let keep = true;
  let open = false;
  const lines = source.replace(/\r\n/g, '\n').split('\n');
  lines.forEach((line, i) => {
    const opened = ONLY_OPEN.exec(line);
    if (opened) {
      if (open) throw new Error(`guide.md:${i + 1}: nested "only" block`);
      const targets = opened[1].split(',').map((t) => t.trim());
      for (const t of targets) {
        if (!TARGETS.includes(t as Target)) throw new Error(`guide.md:${i + 1}: unknown target "${t}"`);
      }
      open = true;
      keep = targets.includes(target);
      return;
    }
    if (ONLY_CLOSE.test(line)) {
      if (!open) throw new Error(`guide.md:${i + 1}: "end only" without "only"`);
      open = false;
      keep = true;
      return;
    }
    if (keep) out.push(line);
  });
  if (open) throw new Error('guide.md: "only" block is not closed');
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

/** Adds one `#` to every Markdown heading outside fenced code. */
export function demoteHeadings(markdown: string): string {
  let inFence = false;
  return markdown
    .split('\n')
    .map((line) => {
      if (FENCE.test(line)) inFence = !inFence;
      if (!inFence && /^#{1,5} /.test(line)) return '#' + line;
      return line;
    })
    .join('\n');
}

export function validateMeta(meta: SkillMeta): string[] {
  const problems: string[] = [];
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(meta.name) || meta.name.length > 64) {
    problems.push('name must be lowercase letters, digits and hyphens, at most 64 characters');
  }
  if (meta.description.length === 0 || meta.description.length > 1024) {
    problems.push(`description must be 1 to 1024 characters (has ${meta.description.length})`);
  }
  if (/[<>]/.test(meta.description)) problems.push('description must not contain angle brackets');
  if (!meta.cursor?.description || !meta.cursor?.globs) problems.push('cursor description and globs are required');
  return problems;
}

export function render(target: Target, guide: string, meta: SkillMeta): string {
  const problems = validateMeta(meta);
  if (problems.length) throw new Error(`skill-src/meta.json: ${problems.join('; ')}`);
  const body = filterForTarget(guide, target);
  switch (target) {
    case 'skill':
      return ['---', `name: ${meta.name}`, `description: ${JSON.stringify(meta.description)}`, '---', '', body].join('\n');
    case 'cursor':
      return [
        '---',
        `description: ${meta.cursor.description}`,
        `globs: ${meta.cursor.globs}`,
        `alwaysApply: ${meta.cursor.alwaysApply}`,
        '---',
        '',
        body,
      ].join('\n');
    case 'agents':
      return [
        AGENTS_START,
        '<!-- Generated by rtl-skill from skill-src/guide.md. Update it with: rtl-skill install codex -->',
        '',
        demoteHeadings(body).trimEnd(),
        '',
        AGENTS_END,
        '',
      ].join('\n');
  }
}

/**
 * Puts the generated section into an AGENTS.md, replacing an older copy
 * between the markers. Text outside the markers is left as it was.
 */
export function mergeAgentsSection(existing: string | null, section: string): string {
  const block = section.trimEnd();
  if (!existing || existing.trim() === '') return block + '\n';
  const text = existing.replace(/\r\n/g, '\n');
  const start = text.indexOf(AGENTS_START);
  const end = text.indexOf(AGENTS_END);
  if (start !== -1 && end > start) {
    return text.slice(0, start) + block + text.slice(end + AGENTS_END.length);
  }
  return text.trimEnd() + '\n\n' + block + '\n';
}

/** GitHub-style heading slug, used to link findings to SKILL.md sections. */
export function slugify(heading: string): string {
  return heading
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s_-]/gu, '')
    .replace(/\s/g, '-');
}

export function headingSlugs(markdown: string): string[] {
  const slugs: string[] = [];
  let inFence = false;
  for (const line of markdown.split('\n')) {
    if (FENCE.test(line)) inFence = !inFence;
    const m = inFence ? null : /^#{1,6} (.+)$/.exec(line);
    if (m) slugs.push(slugify(m[1]));
  }
  return slugs;
}
